import {h,field,table,details,f} from './dom.mjs';
import {commit,store} from './state.mjs';
import {prelabPredictions} from '../efficiency/prelab.mjs';
export function prelabPanel(s,e){const d=e.current,r=s.runs.find(x=>x.id===d?.runId),z=r?prelabPredictions(s,r,d?.efficiency):{ok:false,rows:[],reason:'Choose a seven-peak isocratic reference in Experiment library.'},cfg=s.settings.course?.prelab||{};
 const update=(k,v)=>commit(()=>{const ss=store.workspaces.equipment;ss.settings.course={...ss.settings.course,prelab:{...ss.settings.course?.prelab,[k]:v}};});
 return h('section',{'data-testid':'prelab-predictions'},h('h3','B. Before the lab: predict and compare levers'),h('p',{class:'small'},'Choose a target-peak reference in Experiment library. Compare the worst adjacent Rs and time headroom across eligible runs; the latest run is not automatically the best starting method. Predictions do not mark experiments as performed.'),
 h('p',{class:'small','data-testid':'prelab-gain'},z.ok?`Required N ratio = (Rs spec / current Rs)² = ${f(z.requiredGain,4)}. Reference measured/width-derived N ${f(z.measuredN,0)}; corresponding target ${f(z.targetMeasuredN,0)}. ${z.reason}`:z.reason),
 z.ok?table(['Lever','L (mm)','ID (mm)','PS (µm)','Bead factor','F (mL/min)','tR (min)','BP (psi)','N last¹','Rs worst','Verdict / basis'],z.rows.map(p=>h('tr',{'data-prelab-row':p.id},h('td',p.label),...['L','ID','PS','spp','F','tR','BP','NReferenceCalibrated','Rs'].map(k=>h('td',p.ok?f(p[k],k==='BP'||k==='NReferenceCalibrated'?0:3):'n.a.')),h('td',{class:'small'},p.verdict,p.basis?details('Calculation basis',false,p.basis):null)))):null,
 z.ok?h('p',{class:'tiny'},'¹ Reference row: measured/exported or width-derived N. Other rows: reference-calibrated N = measured N₁ × model N₂/model N₁. It is a prediction, not a new measured peak number. Awesome Rs uses model N ratios; the two N scales are not mixed.'):null,
 details('Optional simulation inputs / Awesome model N',false,h('p',{class:'small'},'Editable trial geometry is not fixed at 150 × 4.6 × 5. It is a hypothetical comparison, never an available stock record or a next experiment. Blank values reset to the labelled reference/default. Product family and physical FPP/SPP construction are separate; verify the exact product.'),field('Trial product family (optional course convention)',h('select',{'data-testid':'prelab-family',onchange:ev=>{const family=ev.target.value;commit(()=>{const ss=store.workspaces.equipment;ss.settings.course={...ss.settings.course,prelab:{...ss.settings.course?.prelab,family:family||null,spp:family==='Raptor'?1.5:family?1:null}};});}},h('option',{value:'',selected:!cfg.family?'selected':null},'No family change declared'),['Pinnacle','Ultra','Force','Raptor'].map(v=>h('option',{value:v,selected:cfg.family===v?'selected':null},v)))),h('div',{class:'row wrap'},[['L','Trial length (mm)',250],['ID','Trial internal diameter (mm)',d?.efficiency?.ref.ID],['PS','Trial particle size (µm)',3],['F','Trial flow (mL/min)',d?.efficiency?.ref.F*.8],['spp','Trial bead factor (explicit model assumption)',1.5]].map(([k,l,v])=>field(l,h('input',{type:'number',min:.000001,step:'any',value:cfg[k]??v??'','data-testid':'prelab-'+k,onchange:ev=>update(k,ev.target.value.trim()===''?null:Number(ev.target.value))})))),
 z.ok?table(['Lever','Awesome model N','Measured-reference calibrated N'],z.rows.filter(p=>p.ok).map(p=>h('tr',h('td',p.label),h('td',f(p.NModel,0)),h('td',f(p.NReferenceCalibrated,0))))):null,h('p',{class:'small'},z.source||'Awesome 260907 and Cycle 3 B6–B8. Trial dimensions are simulations until actual stock is recorded.')));
}
